import org.junit.Test;
import org.jsoup.nodes.TextNode;
import org.jsoup.nodes.Document;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;

public class TextNodeTest {

    @Test
    public void textNodeConstructorTest() {
        String text = "sample text";
        TextNode textNode = new TextNode(text);
        assertEquals(text, textNode.text());
    }

    @Test
    public void nodeNameTest() {
        String text = "sample text";
        TextNode textNode = new TextNode(text);
        assertEquals("#text", textNode.nodeName());
    }

    @Test
    public void textTest() {
        String text = "sample text";
        TextNode textNode = new TextNode(text);
        assertEquals(text, textNode.text());
    }

    @Test
    public void textMutatorTest() {
        String text = "sample text";
        String newText = "new text";
        TextNode textNode = new TextNode(text);
        assertEquals(text, textNode.text());
        textNode.text(newText);
        assertEquals(newText, textNode.text());
    }

    @Test
    public void isBlankTest() {
        String text = " ";
        TextNode textNode = new TextNode(text);
        assertEquals(true, textNode.isBlank());
    }

    @Test
    public void splitTextTest() {
        String text = "sample text";
        int offset = 6;
        TextNode textNode = new TextNode(text);
        TextNode splittedTextNode = textNode.splitText(offset);
        assertEquals(text.substring(0, offset), textNode.text());
        assertEquals(text.substring(offset), splittedTextNode.text());
    }

    @Test
    public void outerHtmlHeadTest() throws IOException {
        String text = "sample text";
        StringBuilder accum = new StringBuilder();
        TextNode textNode = new TextNode(text);
        textNode.outerHtmlHead(accum, 0, new Document.OutputSettings());
        assertEquals(text, accum.toString());
    }

    @Test
    public void cloneTest() {
        String text = "sample text";
        TextNode textNode = new TextNode(text);
        TextNode clonedTextNode = textNode.clone();
        assertEquals(textNode.text(), clonedTextNode.text());
        assertNotEquals(textNode, clonedTextNode);
    }

    @Test
    public void createFromEncodedTest() {
        String encodedText = "sample&nbsp;text";
        TextNode textNode = TextNode.createFromEncoded(encodedText);
        assertEquals("sample text", textNode.text());
    }

    @Test
    public void normaliseWhitespaceTest() {
        String text = "sample    text";
        String normalisedText = TextNode.normaliseWhitespace(text);
        assertEquals("sample text", normalisedText);
    }

    @Test
    public void stripLeadingWhitespaceTest() {
        String text = "         sample text";
        String strippedText = TextNode.stripLeadingWhitespace(text);
        assertEquals("sample text", strippedText);
    }

    @Test
    public void lastCharIsWhitespaceTest() {
        StringBuilder sb = new StringBuilder("sample text ");
        assertEquals(true, TextNode.lastCharIsWhitespace(sb));
    }
}
